from lesson_authoring import entry as E
B=[['拉丁 cavus','空的、凹的']]
W=[
E('concave','英 /ˈkɒŋkeɪv/；美 /kɑːnˈkeɪv/','凹的；向内弯曲的','看汤匙装汤的那一面，它往里面凹。','拉丁 concavus = con- 在此加强 + cavus 空、凹，经法语进入英语。',B+[['拉丁 concavus → 法语 concave → 英语 concave','凹进去的 → 凹的']],'concave surface 是凹面，concave lens 是凹透镜。要先固定观察哪一面：同一把汤匙，装汤的一面凹，背面则凸。','a concave surface；a concave mirror；a concave lens。','concave 向内凹，convex 向外凸。con- 在这里不是“共同拥有一个洞”的机械拼词。',('The inside of a spoon is concave.','汤匙装东西的内侧是凹的。'),('The designer gave the panel a slightly concave shape.','设计师让面板略微向内凹。')),
E('concavity','英 /kɒnˈkævəti/；美 /kɑːnˈkævəti/','凹性；凹陷；凹处','concave 说“这个面是凹的”，concavity 则把凹的形状或那块凹处拿来讨论。','拉丁 concavitas 经法语 concavit 或直接借入；现代可对应 concave + -ity。',B+[['拉丁 concavus → concavitas → 法语 concavit／英语 concavity','凹的 → 凹处、凹的性质']],'the concavity of a surface 讲表面向内弯的性质，a shallow concavity 讲一个浅凹处。数学里也用这个词讨论曲线弯曲的方向，具体要看采用的定义和坐标。','a shallow concavity；surface concavity；the concavity of the curve。','cavity 是内部空腔或洞；concavity 更强调向内弯曲的表面或凹陷。一个浅碟可以有 concavity，却不是洞穴。',('Rainwater collected in a shallow concavity in the rock.','雨水积在岩石的一处浅凹里。'),('The lesson explains how to determine the concavity of a curve.','这节课解释如何判断曲线的凹凸性。'),sources=['https://www.etymonline.com/word/concavity','https://en.wiktionary.org/wiki/concavity']),
E('excavate','/ˈekskəveɪt/','挖掘；发掘；挖空','把泥土一层层取走，让下面的空间或东西露出来。','拉丁 ex- 向外 + cavare 挖空 → excavare，其分词 excavatus 借入英语。',B+[['拉丁 ex- + cavare → excavare、excavatus','向外挖空 → 挖掘'],['英语 excavate','挖土；考古发掘']],'excavate a site 是发掘遗址，excavate a trench 是挖沟。对象可以是被挖开的地方，也可以是从土里发掘出的东西；考古语境通常暗含有计划、有记录的发掘。','excavate a site；excavate a trench；excavate the foundations；excavate remains。','dig 是更日常的“挖”；excavate 较正式，常见于工程和考古。',('Archaeologists excavated the site over several summers.','考古学家利用几个夏天发掘了这处遗址。'),('Workers excavated a trench for the new pipes.','工人挖了一条沟，用来铺设新管道。'),sources=['https://www.etymonline.com/word/excavate','https://en.wiktionary.org/wiki/excavate']),
E('excavation','/ˌekskəˈveɪʃən/','挖掘；考古发掘；挖掘现场或坑穴','把“挖出去”的动作扩大成一项工作，也可以指它挖出的地方。','拉丁 excavatio、excavationem 借入；现代可对应 excavate + -ion。',B+[['拉丁 excavare → excavatio → 英语 excavation','挖空 → 挖掘工作'],['excavation 的结果义','挖掘 → 挖出的坑或发掘现场']],'excavation work 是挖掘作业；during the excavation 可以说在发掘过程中。复数 excavations 也常用于一组考古发掘活动或遗址中的发掘区。','archaeological excavation；excavation work；during excavation；an excavation site。','excavate 是做动作；excavation 是活动、过程或结果。名词有自己的拉丁借入路线，并非只有现代英语加尾缀这一层历史。',('The excavation revealed the remains of a small temple.','发掘揭示了一座小庙的遗迹。'),('Excavation work began before the foundations were laid.','铺设地基之前，挖掘作业先开始了。'),sources=['https://www.etymonline.com/word/excavation','https://en.wiktionary.org/wiki/excavation']),
E('excavator','英 /ˈekskəveɪtə/；美 /ˈekskəveɪtər/','挖掘机；发掘者','工地上伸出长臂、用铲斗把土挖起来的机器。','excavate + -or，可表示执行动作的人或机器。',B+[['拉丁 excavare → 英语 excavate','挖空 → 挖掘'],['excavate + -or → excavator','执行挖掘的人或机器']],'现代工地语境中，excavator 通常是挖掘机；考古叙述中 the excavators of the tomb 也可以指发掘墓葬的人。-or 不能机械限定为职业人物。','an excavator operator；a tracked excavator；the excavators of the site。','excavator 的典型动作是挖取土方；bulldozer 的典型动作是用推土铲推土。两种工程机械不要混译。',('An excavator removed the soil beside the road.','一台挖掘机挖走了路旁的土。'),('The excavators carefully recorded where each object was found.','发掘人员仔细记录了每件物品的出土位置。'),sources=['https://en.wiktionary.org/wiki/excavator'])]
